<p><strong>Đặt trước 2 đến 4 tuần.</strong> Ngày thường đặt trước một hai hôm là đủ, nhưng Tết thì càng sớm càng chắc. Đặt sớm cũng dễ đổi lịch hơn là đặt muộn rồi hết chỗ.</p>
